  let h0 = sha256Constants[0];
  let h1 = sha256Constants[1];
  let h2 = sha256Constants[2];
  let h3 = sha256Constants[3];
  let h4 = sha256Constants[4];
  let h5 = sha256Constants[5];
  let h6 = sha256Constants[6];
  let h7 = sha256Constants[7];

