  for (let i = 0; i < messageBits.length; i += 512) {
    const block = messageBits.slice(i, i + 512);
    const w = new Array(64);
    for (let j = 0; j < 16; j++) {
      w[j] = (block[4 * j] << 24) | (block[4 * j + 1] << 16) | (block[4 * j + 2] << 8) | block[4 * j + 3];
    }
    for (let j = 16; j < 64; j++) {
      w[j] = (sigma1(w[j - 2]) + w[j - 7] + sigma0(w[j - 15]) + w[j - 16]) & 0xffffffff;
    }
