function calculateTotalPrice(quantities, cdTypes, purchaseMethod, customerType) {
  // Initialize total price
  totalPrice = 0

  // Loop through each CD type and quantity
  for i = 0 to quantities.length - 1 {
    // Get CD price and quantity
    cdPrice = CD_PRICES[cdTypes[i]]
    quantity = quantities[i]

    // Apply quantity limit (max 5 CDs)
    if quantity > 5 {
      quantity = 5
