    // Apply discounts
    if purchaseMethod == "MainStore" {
      subtotal *= (1 - DISCOUNTS["MainStore"])
    } else if purchaseMethod == "Window" {
      subtotal *= (1 - DISCOUNTS["Window"])
    }

    if customerType == "Student" {
      subtotal *= (1 - DISCOUNTS["Student"])
    }

    // Add subtotal to total price
    totalPrice += subtotal
  }

  return totalPrice
}

