import React, { useState, useEffect } from 'react';
import styled from 'styled-components';

const Sidebar = () => {
  const [items, setItems] = useState([
    { id: 1, label: 'Item 1', contentId: 'item-1' },
    { id: 2, label: 'Item 2', contentId: 'item-2' },
    { id: 3, label: 'Item 3', contentId: 'item-3' },
    { id: 4, label: 'Item 4', contentId: 'item-4' },
    { id: 5, label: 'Item 5', contentId: 'item-5' },
  ]);

  const [searchTerm, setSearchTerm] = useState('');
  const [activeItemId, setActiveItemId] = useState(null);

  useEffect(() => {
    const handleScroll = () => {
      const currentItem = document.getElementById(activeItemId);
      if (currentItem) {
        currentItem.scrollIntoView({ behavior: 'smooth' });
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, [activeItemId]);

  const handleItemClick = (itemId) => {
    setActiveItemId(itemId);
  };

  const handleSearch = (e) => {
    const searchTerm = e.target.value.toLowerCase();
    setSearchTerm(searchTerm);
    const filteredItems = items.filter((item) => item.label.toLowerCase().includes(searchTerm));
    setItems(filteredItems);
  };

  const filteredItems = items.filter((item) => item.label.toLowerCase().includes(searchTerm));

  return (
    <SidebarContainer>
      <SearchInput
        type="search"
        value={searchTerm}
        onChange={handleSearch}
        placeholder="Search"
      />
      <SidebarList>
        {filteredItems.map((item) => (
          <SidebarItem key={item.id} active={item.id === activeItemId}>
            <SidebarLink onClick={() => handleItemClick(item.id)}>{item.label}</SidebarLink>
          </SidebarItem>
        ))}
      </SidebarList>
    </SidebarContainer>
  );
};

const SidebarContainer = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 200px;
  height: 100vh;
  overflow-y: auto;
  background-color: #f0f0f0;
  padding: 20px;
  border-right: 1px solid #ddd;
