public class LargestElement {
    public static List<Integer> findLargestElement(int[] arr) {
        List<Integer> indices = new ArrayList<>();
        int max = Integer.MIN_VALUE;

        for (int i = 0; i < arr.length; i++) {
            if (arr[i] > max) {
                max = arr[i];
                indices.clear();
                indices.add(i);
            } else if (arr[i] == max) {
                indices.add(i);
            }
        }

        return indices;
    }

