        int[] arr = {3, 5, 2, 7, 7, 1, 9, 7};
        List<Integer> indices = findLargestElement(arr);
        System.out.println("Largest element: " + arr[indices.get(0)]);
        System.out.println("Indices: " + indices);
    }
}
```
