        numbers.add(12);

        int i = 0;
        while (i < numbers.size()) {
            int num = numbers.get(i);
            if (num % 3 == 0) {
                i++; // skip numbers divisible by 3
                continue;
            }
            if (isPrime(num)) {
                System.out.println(num);
            }
            i++;
        }
    }

    public static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        for (int j = 2; j * j <= num; j++) {
            if (num % j == 0) {
                return false;
            }
        }
        return true;
    }
}
```
